import { PLATFORM_VERSION } from '../constants.js';
import { isPlatformVersionAtLeast } from './utils.js';
export const APP_FUNCTIONS_DIRNAME = 'app.functions';
export const APP_FUNCTIONS_MANIFEST_FILENAME = 'serverless.json';
export const DEV_SERVER_DEFAULT_PORT = 6789;
export const EXECUTION_TIMEOUT_MS = 15_000;
export const PRIVATE_APP_ACCESS_TOKEN = 'PRIVATE_APP_ACCESS_TOKEN';
export const HUBSPOT_ACCESS_TOKEN = 'HUBSPOT_ACCESS_TOKEN';
/**
 * Resolves the env-var key under which the app-function access token is
 * injected, matching the backend AccessTokenEnvVarKeyResolver exactly:
 *   - 2027.03 and later (including -beta) → HUBSPOT_ACCESS_TOKEN
 *   - "unstable" sentinel                  → HUBSPOT_ACCESS_TOKEN
 *   - everything else                      → PRIVATE_APP_ACCESS_TOKEN
 */
export function resolveAccessTokenKey(platformVersion) {
    if (platformVersion === PLATFORM_VERSION.UNSTABLE) {
        return HUBSPOT_ACCESS_TOKEN;
    }
    return isPlatformVersionAtLeast(platformVersion, 2027, 3)
        ? HUBSPOT_ACCESS_TOKEN
        : PRIVATE_APP_ACCESS_TOKEN;
}
export const getSecretsInContext = (accessTokenKey) => [
    accessTokenKey,
    'HS_ENVIRONMENT',
    'HS_HUBLET',
    'HS_SERVERLESS_FUNCTION_ID',
];
